import {wordClassLabel} from './word-class-labels.mjs';
import {h,icon,button as btn,spoken,plural,teachingText} from './ui.mjs';
import {referenceSelection,referenceTabs as tabs,tenseNames} from './reference-tools.mjs';
import {referenceEntry,referenceExample} from './reference-entry.mjs';
import {getWordEntries,isMarked} from './course.mjs';

function pager(data){if(data.pages===1)return `<p class="reference-count" role="status">${data.total} ${plural(data.total,['запись','записи','записей'])}</p>`;return `<div class="reference-pager">${btn('В начало','reference-page','secondary pager-edge',`data-value="1" ${data.page===1?'disabled':''}`)}${btn('Назад','reference-page','secondary',`data-value="${data.page-1}" ${data.page===1?'disabled':''}`)}<span role="status">${data.page} / ${data.pages} · ${data.total} ${plural(data.total,['запись','записи','записей'])}</span>${btn('Далее','reference-page','secondary',`data-value="${data.page+1}" ${data.page===data.pages?'disabled':''}`)}${btn('В конец','reference-page','secondary pager-edge',`data-value="${data.pages}" ${data.page===data.pages?'disabled':''}`)}</div>`;}
function perfect(v,past=false){return v.auxiliary.split('/').map(aux=>spoken(`${past?(aux==='er'?'var':'havde'):aux} ${v.participle}`)).join('<br>');}
function verbs(data){
 const mobile=`<div class="verb-compact-list">${data.items.map(v=>referenceEntry(v.infinitive,v.ru,`<dl class="compact-forms">${[['Nutid · настоящее',spoken(v.present)],['Datid · прошедшее',spoken(v.past)],['Førnutid · перфект',perfect(v)],['Førdatid · предпрошедшее',perfect(v,true)],['Bydemåde · повелительное',v.imperative?spoken(v.imperative):'Не используется']].map(([label,form])=>`<div><dt>${label}</dt><dd>${form}</dd></div>`).join('')}</dl>${v.note?`<p class="field-note">${teachingText(v.note)}</p>`:''}`)).join('')}</div>`;
 const table=`<div class="reference-table-wrap" tabindex="0" role="region" aria-label="Таблица форм глаголов"><table class="reference-table"><thead><tr><th scope="col">Глагол · verbum</th><th scope="col">Nutid</th><th scope="col">Datid</th><th scope="col">Førnutid</th><th scope="col">Førdatid</th><th scope="col">Bydemåde</th></tr></thead><tbody>${data.items.map(v=>`<tr><th scope="row"><b>${spoken(v.infinitive)}</b><small>${h(v.ru)}</small>${v.note?`<details><summary>Употребление</summary><p>${teachingText(v.note)}</p></details>`:''}</th><td>${spoken(v.present)}</td><td>${spoken(v.past)}</td><td>${perfect(v)}</td><td>${perfect(v,true)}</td><td>${v.imperative?spoken(v.imperative):'Не используется'}</td></tr>`).join('')}</tbody></table></div>`;
 return `<p class="field-note">Открой глагол, чтобы сравнить формы. Вспомогательный глагол зависит от конструкции.</p>${mobile}${table}`;
}
function adjectives(data){return `<div class="reference-list">${data.items.map(a=>referenceEntry(a.positive,a.ru,`<dl class="compact-forms">${[['Положительная',a.positive],['Сравнительная',a.comparative],['Превосходная',a.superlative]].map(([name,form])=>`<div><dt>${name}</dt><dd>${spoken(form)}</dd></div>`).join('')}</dl>${a.note?`<p class="field-note">${teachingText(a.note)}</p>`:''}`,{badge:a.wordClass==='adjective'?wordClassLabel('adjective'):'Количество'})).join('')}</div>`;}
function particles(data){return `<p class="info-panel">Одинаковая частица не даёт одного перевода. Сравнивай целые сочетания и ситуацию. Слитный глагол и глагол с отдельной частицей могут означать разное.</p><div class="particle-families">${data.items.map(f=>`<details class="panel particle-family"><summary><b>${h(f.base)}</b><span>${h(f.ru)}</span>${icon('chevron')}</summary><div>${f.words.map(w=>`<article><h3>${spoken(w.da)}</h3><b>${h(w.ru)}</b><p>${h(w.note||'')}</p><div class="word-example"><p lang="da">${h(w.exampleDa)}</p><small>${h(w.exampleRu)}</small></div></article>`).join('')}</div></details>`).join('')}</div>`;}
function informal(data){const labels={mild:'Мягкое',moderate:'Грубое',strong:'Сильное'};return `<p class="notice warning">Для понимания услышанного. Сила зависит от тона и ситуации. Эти выражения не попадают в ежедневный план.</p><div class="reference-list">${data.items.map(w=>referenceEntry(w.da,w.ru,`<p class="field-note">${teachingText(w.register)}</p><p>${teachingText(w.note)}</p>${referenceExample(w.exampleDa,w.exampleRu)}<p class="field-note">Нейтральнее: ${spoken(w.neutral)}</p>`,{badge:labels[w.strength]||w.strength,tone:w.strength==='strong'?'coarse':''})).join('')}</div>`;}
function entryActions(w,c,aliases){
 const saved=isMarked(aliases.get(w.id)||w,c.state.bookmarks),difficult=isMarked(aliases.get(w.id)||w,c.state.difficult);
 return `<div class="common-card-actions"><button class="remember-button ${saved?'active':''}" data-action="bookmark" data-id="${w.id}" aria-pressed="${saved}">${icon(saved?'check':'bookmark')}${saved?'Сохранено':'Сохранить'}</button><button class="remember-button ${difficult?'active':''}" data-action="difficult" data-id="${w.id}" aria-pressed="${difficult}">${icon('brain')}${difficult?'В сложных':'Не запомнил'}</button>${btn('Учить','train-word','secondary',`data-id="${w.id}"`)}</div>`;
}
function common(data,c){
 const aliases=new Map(getWordEntries(c.state).flatMap(entry=>entry.ids.map(id=>[id,entry])));
 return `<div class="reference-list">${data.items.map(w=>referenceEntry(w.da,w.ru,`${w.forms?`<dl class="compact-forms">${w.forms.slice(1).map(f=>`<div><dt>${h(f.label)}</dt><dd>${spoken(f.da)}</dd></div>`).join('')}</dl>`:''}<p class="field-note">${teachingText(w.note)}</p>${referenceExample(w.exampleDa,w.exampleRu)}${entryActions(w,c,aliases)}`,{badge:c.referenceData.categories.find(cat=>cat.id===w.category)?.title})).join('')}</div>`;
}
function everyday(data,c){
 const aliases=new Map(getWordEntries(c.state).flatMap(entry=>entry.ids.map(id=>[id,entry])));
 const categories=c.referenceTab==='spoken'?c.referenceData.spokenCategories:c.referenceData.dailyCategories;
 return `<div class="reference-list">${data.items.map(w=>referenceEntry(w.da,w.ru,`${w.wordClass?`<p class="entry-class">${h(wordClassLabel(w.wordClass)||w.wordClass)} · ${h(w.level)}</p>`:''}${w.heard?`<div class="heard-form"><b>${h(w.heard)}</b><small>Так могут записывать звучание. Не стандартная орфография.</small></div>`:''}${w.note?`<p class="field-note">${teachingText(w.note)}</p>`:''}${referenceExample(w.exampleDa,w.exampleRu)}${entryActions(w,c,aliases)}`,{badge:categories?.find(cat=>cat.id===w.category)?.title})).join('')}</div>`;
}
function tenses(data){return `<p class="info-panel">Время описывает отношение события к настоящему или другому моменту. Инфинитив и повелительная форма — отдельные формы глагола, их можно посмотреть в таблице.</p><div class="tense-guides">${data.items.map(l=>{
 const key=l.id.replace('form-lesson-',''),[da,ru]=tenseNames[key];
 return `<article class="panel reference-card tense-guide"><div class="section-title"><div><span class="eyebrow">${h(da)}</span><h2>${h(ru)}</h2></div><span class="pill purple">${l.level}</span></div><p>${teachingText(l.rule)}</p><div class="tense-examples">${l.items.slice(0,2).map(p=>`<div class="word-example"><p lang="da">${h(p.da)}</p><small>${h(p.ru)}</small></div>`).join('')}</div>${btn('Практика: '+h(l.title),'lesson-intro','secondary',`data-id="${l.id}"`)}</article>`;
 }).join('')}</div>`;}
export function renderReference(c,renderLessons){
 const source=c.referenceData,{tab,filters,selected,categories,data,rows}=referenceSelection(c);
 const lessonList=tab==='verbs'?c.referenceLessons.forms:tab==='adjectives'?c.referenceLessons.quantity:tab==='particles'?c.referenceLessons.particles:[];
 return `<div class="page-heading reference-heading"><div><h1>Слова и выражения</h1><p>Открой строку для примера и форм.</p></div></div><div class="filter-tabs reference-tabs" role="group" aria-label="Раздел справочника">${tabs.map(([id,label])=>`<button class="${tab===id?'active':''}" data-action="reference-tab" data-value="${id}" aria-pressed="${tab===id}">${label}</button>`).join('')}</div><div class="reference-toolbar"><label class="search-box reference-search">${icon('search')}<input id="reference-search" type="search" value="${h(c.referenceQuery)}" placeholder="Датское слово, форма или перевод" aria-label="Поиск в справочнике"></label>${filters.length?`<label class="reference-category">${tab==='tenses'?'Время':tab==='verbs'?'Группа глаголов':'Категория слов'}<select id="reference-category" data-reference-category aria-label="${tab==='tenses'?'Время':tab==='verbs'?'Группа глаголов':'Категория слов'}"><option value="all" ${selected==='all'?'selected':''}>${tab==='tenses'?'Все времена':'Все категории'}</option>${filters.map(([id,label])=>`<option value="${id}" ${selected===id?'selected':''}>${h(label)}${categories.find(cat=>cat.id===id)?.da?' · '+h(categories.find(cat=>cat.id===id).da):''}</option>`).join('')}</select></label>`:''}</div>${selected!=='all'&&categories.find(cat=>cat.id===selected)?.note?`<p class="field-note">${teachingText(categories.find(cat=>cat.id===selected).note)}</p>`:''}${['daily','spoken','common'].includes(tab)&&data.total?`<div class="reference-practice"><span>${rows.length} ${plural(rows.length,['запись','записи','записей'])} в выбранной группе</span>${btn('Учить группу','reference-train','primary')}</div>`:''}${pager(data)}${!data.total?'<div class="empty"><h3>Ничего не найдено</h3><p>Измени слово, перевод или категорию.</p></div>':({verbs,adjectives,particles,informal,common,tenses,daily:everyday,spoken:everyday})[tab](data,c)}${data.total>10?pager(data):''}${['daily','spoken'].includes(tab)?`<details class="coverage-note"><summary>Об охвате и произношении</summary><p>${tab==='daily'?`${(source.daily||[]).length} слов и сочетаний по ${(source.dailyCategories||[]).length} ситуациям. Это учебная подборка, а не полный частотный словарь.`:'Разговорные реплики и варианты записи речи. Озвучка читает стандартную форму; она не воспроизводит все сокращения живой речи.'}</p></details>`:''}${lessonList.length?`<section class="course-section"><div class="section-title"><div><h2>Применить в предложениях</h2><p>Уроки сохраняют результат и добавляют ошибки в повторение.</p></div></div>${renderLessons(lessonList,c.state)}</section>`:''}`;
}
